import { Bot, Braces, BriefcaseBusiness, Check, Code2, LockKeyhole, Palette, ShieldCheck, UserRound } from 'lucide-react'
import { useState } from 'react'
import type { MemoryCategory } from '../domain/memory'
import { useMemory } from '../state/MemoryContext'
import styles from './UtilityPages.module.css'

const categories: Array<{ name: MemoryCategory; icon: typeof Code2; note: string }> = [
  { name: '코딩', icon: Code2, note: '스택, 도구, 개발 습관' },
  { name: '일', icon: BriefcaseBusiness, note: '프로젝트, 목표, 업무 방식' },
  { name: '취향', icon: Palette, note: '디자인, 표현, 선호' },
  { name: '개인', icon: UserRound, note: '생활, 신상, 개인 맥락' },
]

const appMeta: Record<string, { icon: typeof Bot; description: string; badge: string }> = {
  ChatGPT: { icon: Bot, description: '기본 대화 및 프로젝트', badge: 'OPENAI' },
  '회사 AI': { icon: BriefcaseBusiness, description: '조직에서 관리하는 어시스턴트', badge: 'WORK' },
  '코딩 어시스턴트': { icon: Braces, description: 'IDE와 연결된 개발 도구', badge: 'LOCAL' },
}

export function AccessPage() {
  const { workspace, updateAccess } = useMemory()
  const [overrides, setOverrides] = useState<Record<string, boolean>>({})
  const apps = Array.from(new Map(workspace.accessRules.map((rule) => [rule.appId, rule.appName])))

  const enabledFor = (appId: string, category: MemoryCategory) => {
    const key = `${appId}:${category}`
    return key in overrides ? overrides[key] : Boolean(workspace.accessRules.find((rule) => rule.appId === appId && rule.category === category)?.enabled)
  }

  const toggle = (appId: string, category: MemoryCategory) => {
    const next = !enabledFor(appId, category)
    setOverrides((current) => ({ ...current, [`${appId}:${category}`]: next }))
    void updateAccess(appId, category, next)
  }

  return (
    <section className={styles.page} aria-labelledby="access-title">
      <header className={styles.pageHeader}>
        <div>
          <span className={styles.eyebrow}>MEMORY PERMISSIONS</span>
          <h1 id="access-title">어떤 AI가, 무엇을 기억할 수 있나요?</h1>
          <p>기억은 하나지만 접근 범위는 도구마다 다릅니다. 범주 단위로 안전하게 나누세요.</p>
        </div>
        <div className={styles.securityBadge}><ShieldCheck size={15} /><span><strong>기기 내 암호화</strong><small>권한 변경은 즉시 적용됩니다</small></span></div>
      </header>

      <div className={styles.accessSummary}>
        <div><LockKeyhole size={15} /><span><strong>{apps.length}개 AI 연결됨</strong><small>개인 기억은 기본적으로 비공개입니다.</small></span></div>
        <p><i /> 모든 권한 정상</p>
      </div>

      <div className={`${styles.panel} ${styles.accessPanel}`}>
        <div className={styles.matrixHeader}>
          <div><span className={styles.eyebrow}>CONNECTED AI</span><strong>연결된 도구</strong></div>
          {categories.map(({ name, icon: Icon, note }) => <div key={name}><Icon size={14} /><strong>{name}</strong><small>{note}</small></div>)}
        </div>

        {apps.map(([appId, appName]) => {
          const meta = appMeta[appName] ?? appMeta.ChatGPT
          const Icon = meta.icon
          return (
            <div className={styles.matrixRow} key={appId}>
              <div className={styles.appIdentity}>
                <span className={styles.appIcon}><Icon size={17} /></span>
                <span><strong>{appName}</strong><small>{meta.description}</small></span>
                <em>{meta.badge}</em>
              </div>
              {categories.map(({ name }) => {
                const enabled = enabledFor(appId, name)
                return (
                  <div className={styles.ruleCell} key={name}>
                    <button type="button" role="switch" aria-checked={enabled} aria-label={`${appName} ${name} 기억`} className={styles.switch} onClick={() => toggle(appId, name)}><span /></button>
                    <small>{enabled ? '허용됨' : '차단됨'}</small>
                  </div>
                )
              })}
            </div>
          )
        })}
      </div>

      <footer className={styles.accessFooter}>
        <span><Check size={13} /> 설정은 이 브라우저의 Memory OS에 저장됩니다.</span>
        <span>최근 권한 검토 · 오늘</span>
      </footer>
    </section>
  )
}

